import{_ as r,l as i,o as e,c as s,v as t,p as l,x as n,d,i as p,S as u}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"报价填塞","description":"","frontmatter":{"title":"报价填塞","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/quote-stuffing.md","filePath":"quant/quote-stuffing.md","lastUpdated":1789023840000}'),h={name:"quant/quote-stuffing.md"};function c(E,a,f,_,m,A){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="报价填塞" tabindex="-1">报价填塞 <a class="header-anchor" href="#报价填塞" aria-label="Permalink to &quot;报价填塞&quot;">​</a></h1><div class="epigraph"><p>报价填塞是在极短时间内提交并撤销大量订单，占用撮合与行情通道，使别人看到的簿延迟或残缺。它攻击的是别人的信息集与速度，而不必完成成交。</p><footer>—— Egginton, Van Ness and Van Ness, Quote stuffing, Financial Review, 2016；技术背景见 Hasbrouck and Saar 对低延迟订单流的讨论</footer></div><p><a href="/quant/flash-crash-2010">闪电崩盘</a>是供给撤退的价格路径。缺口是另一种伤害流动性的技术：不一定把簿撤空，而是用消息洪水让对手的状态机变慢。Egginton、Van Ness 与 Van Ness（2016）度量报价填塞时段的市场质量。本课写机制与识别，严格区别于下一课有虚假意向的幌骚，也区别于正当的高频改价。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>正常做市已经有高撤单率。填塞的额外特征是：消息率相对成交异常高、集中在极短窗口、往往不改变对提交者自己有用的队列位置，却造成行情拥堵。别人的「看见的簿」变成过时状态，其撤单与狙击决策基于错的 \\(\\rho\\)，被捡与误吃上升。问题是如何在数据里把拥堵攻击从「新闻到达时大家一起改价」分开：后者是公共信息的合法同步更新，前者是制造人为延迟。</p><p>Budish 竞赛假设每个人看见同一条新闻。填塞破坏这个共同信息集，是对透明的攻击，回到 Bloomfield–O&#39;Hara 的谁看见什么。</p><h3 id="通道是稀缺资源" tabindex="-1">通道是稀缺资源 <a class="header-anchor" href="#通道是稀缺资源" aria-label="Permalink to &quot;通道是稀缺资源&quot;">​</a></h3><p>撮合引擎、行情组播、参与者的解析队列都有容量。先到者通吃的协议里，让别人的队列变长，等价于让自己相对变快。填塞因此可以是速度竞赛的阴暗技术：不投资更短的线，而增加别人的 \\(d\\)。社会成本是全市场状态变差，不只是租金再分配。</p><p><span class="marginnote">监管与交易所后来用消息比、撤单费、节流来对通道定价。本课只把通道写成稀缺，具体规则表留在市场设计。不要把未经验证的「某年某所某算法」写成事实。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>度量：在毫秒窗内计数新增+撤销，相对成交、相对该证券的历史分位。识别：窗口内价差、深度、中点波动、其他参与者的消息延迟（若有时间戳质量）。Egginton 等人报告填塞窗内质量恶化。因果仍难：也许是同一新闻引起填塞状改价与质量恶化。工具可以用意外的引擎减速、或只影响行情不改变价值的纯消息事件。</p><p>与 Hasbrouck VAR：填塞期报价新息充满噪声，信息含量估计应切开这些窗，否则暂时成分被高估。</p>',12)),(e(),l(u,null,{default:n(()=>[p(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20LR%0A%20%20Flood%5B%22%E7%9F%AD%E7%AA%97%E6%B5%B7%E9%87%8F%E5%A2%9E%E6%92%A4%22%5D%20--%3E%20Cong%5B%22%E8%A1%8C%E6%83%85%20%2F%20%E6%92%AE%E5%90%88%E6%8B%A5%E5%A0%B5%22%5D%0A%20%20Cong%20--%3E%20Late%5B%22%E5%AF%B9%E6%89%8B%E7%8A%B6%E6%80%81%E8%BF%87%E6%97%B6%22%5D%0A%20%20Late%20--%3E%20Harm%5B%22%E8%AF%AF%E5%90%83%20%2F%20%E8%A2%AB%E6%8D%A1%20%2F%20%E5%8A%A0%E5%AE%BD%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>填塞改变的是条件信息集的时钟。Easley–O&#39;Hara 的学习假设每笔方向被同时看见；拥堵时一部分人看见，一部分人看见延迟序列，信念分叉，Glosten 曲线对慢的人错误开口。快的填塞者可以在自己制造的过时上交易——这已经接近操纵的经济定义（制造虚假市场状态并从中交易），即使订单曾经「真实」存在过几个微秒。</p><p>正当高频做市的改价通常跟随中点或库存，订单在附近价位重挂。填塞更常扫过大量远离成交的价位，或在同一档反复增撤而不改变净深度。行为特征比消息率阈值更有内容。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>没有成交的高消息率也可能是测试、错误环路、或 pro-rata 堆量。执法需要模式与意图，本课不给法律标准。加密与某些外汇平台的通道更脆，同构现象更频繁，但文献样本以美股为主。把所有闪单叫做填塞，会把撤单博弈课的理性寿命选择一网打尽。</p><p><span class="marginnote">回测若在填塞窗用官方 L2 当真实可成交，你比当时的慢参与者还乐观——你在用事后干净的重建，他们当时没看到。</span></p><p>下一课的幌骚攻击的是可见供需的内容，填塞攻击的是别人看见该内容的时钟。两者可以叠用，识别上仍应先分开：一个改延迟，一个伪造深度。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>报价填塞用消息洪水占用通道，使对手信息集过时，是对速度与透明的攻击。</li><li>须与新闻同步改价、理性短寿命做市区分；远离成交价的无效增撤是更强特征。</li><li>通道稀缺时，制造别人的延迟等价于相对加速。</li><li>出处：Egginton, Van Ness and Van Ness, <em>Financial Review</em>, 2016；低延迟订单流见 Hasbrouck and Saar, 2013。</li></ul>',9))])}const B=r(h,[["render",c]]);export{g as __pageData,B as default};
